var allMap = new Map();
export function getJointMgr(sp) {
    let ret = allMap.get(sp);
    if (!ret) {
        ret = new IK_JointManager();
    }
    allMap.set(sp, ret);
    return ret;
}
export class IK_JointManager {
    constructor() {
        this._mapBoneJoint = {};
    }
    getJoint(name) {
        return this._mapBoneJoint[name];
    }
    addJoint(name, joint) {
        this._mapBoneJoint[name] = joint;
    }
}
