import { Quaternion } from "../maths/Quaternion";
import { Vector3 } from "../maths/Vector3";
let xUnitVec3;
let yUnitVec3;
let tmpVec3;
export function quaternionFromTo(from, to, out) {
    if (!xUnitVec3) {
        xUnitVec3 = new Vector3(1, 0, 0);
        yUnitVec3 = new Vector3(0, 1, 0);
        tmpVec3 = new Vector3();
    }
    var dot = Vector3.dot(from, to);
    if (dot < -0.99999999) {
        Vector3.cross(xUnitVec3, from, tmpVec3);
        if (Vector3.scalarLength(tmpVec3) < 0.000001)
            Vector3.cross(yUnitVec3, from, tmpVec3);
        Vector3.normalize(tmpVec3, tmpVec3);
        Quaternion.createFromAxisAngle(tmpVec3, Math.PI, out);
        return true;
    }
    else if (dot > 0.99999999) {
        out.x = 0;
        out.y = 0;
        out.z = 0;
        out.w = 1;
        return false;
    }
    else {
        Vector3.cross(from, to, tmpVec3);
        out.x = tmpVec3.x;
        out.y = tmpVec3.y;
        out.z = tmpVec3.z;
        out.w = 1 + dot;
        out.normalize(out);
        return true;
    }
    return false;
}
export function delay(time) {
    return new Promise(function (resolve) {
        setTimeout(resolve, time);
    });
}
let dv1 = new Vector3();
let dv2 = new Vector3();
export function isCollinear(p1, p2, p3, epsilon = 1e-6) {
    const v1 = p2.vsub(p1, dv1).normalize();
    const v2 = p3.vsub(p1, dv2).normalize();
    const dot = Math.abs(v1.dot(v2));
    return Math.abs(dot - 1) < epsilon;
}
export function solveLambdaForNormEquality(v1, v2, v3) {
    const EPS = 1e-8;
    const a = Vector3.dot(v2, v2);
    const b = 2 * Vector3.dot(v1, v2);
    const c = Vector3.dot(v1, v1) - Vector3.dot(v3, v3);
    if (Math.abs(a) < EPS) {
        if (Math.abs(b) < EPS) {
            return Math.abs(c) < EPS ? 0 : NaN;
        }
        const x = -c / b;
        return x >= -EPS ? (x < 0 ? 0 : x) : NaN;
    }
    const delta = b * b - 4 * a * c;
    if (delta < -EPS) {
        return NaN;
    }
    if (Math.abs(delta) <= EPS) {
        const x = -b / (2 * a);
        return x >= -EPS ? (x < 0 ? 0 : x) : NaN;
    }
    const sqrtDelta = Math.sqrt(delta);
    const r1 = (-b + sqrtDelta) / (2 * a);
    const r2 = (-b - sqrtDelta) / (2 * a);
    let has1 = false, has2 = false;
    let c1 = 0, c2 = 0;
    if (r1 >= -EPS) {
        has1 = true;
        c1 = r1 < 0 ? 0 : r1;
    }
    if (r2 >= -EPS) {
        has2 = true;
        c2 = r2 < 0 ? 0 : r2;
    }
    if (!has1 && !has2)
        return NaN;
    if (has1 && !has2)
        return c1;
    if (!has1 && has2)
        return c2;
    return Math.abs(c1) <= Math.abs(c2) ? c1 : c2;
}
export function solveLookat(target, endPose, deltaQ) {
    let ele = endPose.elements;
    let endPos = new Vector3(ele[12], ele[13], ele[14]);
    let endDir = new Vector3(ele[8], ele[9], ele[10]);
    endDir.normalize();
    let k = solveLambdaForNormEquality(endPos, endDir, target);
    if (isNaN(k)) {
        return false;
    }
    let v1 = new Vector3();
    Vector3.scale(endDir, k, v1);
    Vector3.add(endPos, v1, v1);
    v1.normalize();
    let t = target.clone().normalize();
    quaternionFromTo(v1, t, deltaQ);
    return true;
}
export function ripMatScale(mat) {
    let e = mat.elements;
    let d = Math.sqrt(e[0] ** 2 + e[1] ** 2 + e[2] ** 2);
    e[0] /= d;
    e[1] /= d;
    e[2] /= d;
    d = Math.sqrt(e[4] ** 2 + e[5] ** 2 + e[6] ** 2);
    e[4] /= d;
    e[5] /= d;
    e[6] /= d;
    d = Math.sqrt(e[8] ** 2 + e[9] ** 2 + e[10] ** 2);
    e[8] /= d;
    e[9] /= d;
    e[10] /= d;
    return mat;
}
function VecAngle(v1, v2) {
    let v1l = v1.length();
    let v2l = v2.length();
    let dot = v1.dot(v2);
    let v = dot / v1l / v2l;
    if (v > 1)
        v = 1;
    if (v < -1)
        v - 1;
    return Math.acos(v);
}
export function getVecAngInPlane(axisPos, axis, zero, vec) {
    let v1 = new Vector3();
    vec.vsub(axisPos, v1);
    let dot = Vector3.dot(v1, axis);
    let projVec = new Vector3(v1.x - dot * axis.x, v1.y - dot * axis.y, v1.z - dot * axis.z);
    let dot1 = Vector3.dot(zero, axis);
    let projZero = new Vector3(zero.x - dot1 * axis.x, zero.y - dot1 * axis.y, zero.z - dot1 * axis.z);
    let angle = VecAngle(projZero, projVec);
    let cross = new Vector3();
    Vector3.cross(projZero, projVec, cross);
    if (Vector3.dot(cross, axis) < 0) {
        angle = -angle;
    }
    return angle;
}
export class NumberSmooth {
    constructor(k = 0.5) {
        this.k = k;
        this.lastv = 0;
    }
    in(v) {
        let k = this.k;
        let k1 = 1 - k;
        this.lastv = v * k + this.lastv * k1;
        return this.lastv;
    }
}
export class Vec3Smooth {
    constructor(k = 0.5) {
        this.k = k;
        this.lastV = null;
    }
    in(v) {
        let k = this.k;
        let k1 = 1 - k;
        if (!this.lastV)
            this.lastV = v.clone();
        let v0 = this.lastV;
        let v1 = v;
        this.lastV.setValue(v1.x * k + v0.x * k1, v1.y * k + v0.y * k1, v1.z * k + v0.z * k1);
        return this.lastV;
    }
}
