import { Sprite3D } from "../d3/core/Sprite3D";
import { Vector3 } from "../maths/Vector3";
export class IK_Target {
    constructor(pos, dir) {
        this.targetSprite = null;
        this._pos = new Vector3();
        this._dir = new Vector3(0, 1, 0);
        if (pos instanceof Sprite3D) {
            this.targetSprite = pos;
        }
        else {
            if (pos)
                pos.cloneTo(this._pos);
            if (dir)
                dir.cloneTo(this._dir);
        }
    }
    getPose(mat) {
        if (this.targetSprite) {
            this.targetSprite.transform.worldMatrix.cloneTo(mat);
            return mat;
        }
        return null;
    }
    get pos() {
        if (this.targetSprite) {
            return this.targetSprite.transform.position;
        }
        return this._pos;
    }
    set pos(p) {
        if (this.targetSprite) {
            this.targetSprite = null;
        }
        p.cloneTo(this._pos);
    }
    get dir() {
        if (this.targetSprite) {
            let e = this.targetSprite.transform.worldMatrix.elements;
            this._dir.setValue(e[4], e[5], e[6]);
            this._dir.normalize();
        }
        return this._dir;
    }
    set dir(v) {
        if (this.targetSprite) {
            this.targetSprite = null;
        }
        v.cloneTo(this._dir);
    }
}
