export class IK_ConstraintData {
    constructor() {
        this._xmin = -45;
        this._xmax = 45;
        this._ymin = -45;
        this._ymax = 45;
        this._zmin = 0;
        this._zmax = 0;
        this.enable = true;
        this.type = 'hinge';
        this.space = null;
        this.constraintBone = false;
        this.visualHeight = 0.5;
    }
    set xmin(v) {
        this._xmin = v;
        if (this._xmax < v) {
            this.xmax = v;
        }
    }
    get xmin() {
        return this._xmin;
    }
    set xmax(v) {
        this._xmax = v;
        if (this._xmin > v) {
            this.xmin = v;
        }
    }
    get xmax() {
        return this._xmax;
    }
    set ymin(v) {
        this._ymin = v;
        if (this._ymax < v) {
            this.ymax = v;
        }
    }
    get ymin() {
        return this._ymin;
    }
    set ymax(v) {
        this._ymax = v;
        if (this._ymin > v) {
            this.ymin = v;
        }
    }
    get ymax() {
        return this._ymax;
    }
    set zmin(v) {
        this._zmin = v;
        if (this._zmax < v) {
            this.zmax = v;
        }
    }
    get zmin() {
        return this._zmin;
    }
    set zmax(v) {
        this._zmax = v;
        if (this._zmin > v) {
            this.zmin = v;
        }
    }
    get zmax() {
        return this._zmax;
    }
}
